query PullRequestByNumber($owner: String!, $repo: String!, $pr_number: Int!) {
	repository(owner: $owner, name: $repo) {
		pullRequest(number: $pr_number) {number,title,body,state,headRefName,baseRefName,additions,deletions,changedFiles,files(first: 100) {nodes {additions,deletions,path,changeType}},commits(first: 100) {nodes {commit {authors(first:100) {nodes {name,email,user{id,login}}},messageHeadline,messageBody,oid,committedDate,authoredDate}}},reviewDecision,mergeable,url,id}
	}
}
